import subprocess
import shutil
import os

def task_func(script_path: str, temp_dir: str) -> str:
    # Ensure the temp directory exists and is empty
    if os.path.exists(temp_dir):
        shutil.rmtree(temp_dir)
    os.makedirs(temp_dir, exist_ok=True)

    # Copy the script into the temp directory
    script_name = os.path.basename(script_path)
    temp_script_path = os.path.join(temp_dir, script_name)
    try:
        shutil.copy2(script_path, temp_script_path)
    except Exception:
        return "Script execution failed!"

    # Execute the script in the temp directory
    try:
        result = subprocess.run(
            ["python", script_name],
            cwd=temp_dir,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        if result.returncode == 0:
            return "Script executed successfully!"
        else:
            return "Script execution failed!"
    except Exception:
        return "Script execution failed!"
